html:
{%- set is_pickup = doc.pickup and not doc.dropoff -%}
{%- set party_name = frappe.db.get_value("Pickup", doc.pickup, "customer_name") if is_pickup else doc.supplier_name -%}
<style>
@page {
    size: 80mm auto;
    margin: 2mm;
}

.thermal-receipt {
    font-family: 'Sarabun', 'Tahoma', sans-serif;
    font-size: 12px;
    line-height: 1.45;
    width: 76mm;
    margin: 0 auto;
    padding: 2mm;
    color: #000;
}

.receipt-header {
    text-align: center;
    border-bottom: 1px dashed #000;
    padding-bottom: 3mm;
    margin-bottom: 3mm;
}

.company-name {
    font-size: 16px;
    font-weight: bold;
    margin: 2mm 0;
}

.company-name-th {
    font-size: 12px;
    font-weight: bold;
    margin: 0 0 1mm 0;
}

.company-address {
    font-size: 10px;
    margin: 1mm 0;
}

.doc-title {
    font-size: 14px;
    font-weight: bold;
    margin: 2mm 0;
}

.doc-number {
    font-size: 11px;
    color: #000;
}

.receipt-body {
    margin: 2mm 0;
}

.info-section {
    border-bottom: 1px dashed #000;
    padding-bottom: 2mm;
    margin-bottom: 2mm;
}

.info-row {
    display: flex;
    justify-content: space-between;
    margin: 1mm 0;
    font-size: 11px;
}

.info-label {
    color: #000;
}

.info-value {
    font-weight: bold;
    text-align: right;
}

.weight-display {
    text-align: center;
    margin: 3mm 0;
    padding: 2mm 0;
}

.weight-value-huge {
    font-size: 36px;
    font-weight: bold;
    line-height: 1;
}

.weight-unit {
    font-size: 14px;
    font-weight: bold;
}

.weight-type-row {
    display: flex;
    justify-content: center;
    gap: 5mm;
    margin: 2mm 0;
    padding-bottom: 2mm;
    border-bottom: 1px dashed #000;
}

.weight-type-option {
    border: 1px solid #000;
    padding: 2mm 3mm;
    text-align: center;
    font-size: 10px;
}

.weight-type-option.checked {
    border: 2px solid #000;
}

.checkbox {
    font-family: monospace;
    font-size: 12px;
    font-weight: bold;
}

.option-label {
    font-size: 10px;
}

.info-row-box {
    display: flex;
    justify-content: space-between;
    border: 1px solid #000;
    padding: 2mm;
    margin: 2mm 0;
    font-size: 10px;
}

.info-box-item {
    text-align: center;
}

.box-label {
    display: block;
    font-size: 10px;
}

.box-value {
    font-weight: bold;
    font-size: 11px;
}

.reweight-badge {
    border: 2px solid #000;
    padding: 1mm 2mm;
    font-size: 11px;
    font-weight: bold;
    text-align: center;
    margin: 2mm 0;
}

.remarks-section {
    border-top: 1px dashed #000;
    margin-top: 2mm;
    padding-top: 2mm;
    font-size: 10px;
}

.receipt-footer {
    border-top: 1px dashed #000;
    margin-top: 3mm;
    padding-top: 2mm;
    text-align: center;
    font-size: 10px;
    color: #000;
}

.operator-info {
    margin: 1mm 0;
}

.thank-you {
    font-size: 11px;
    font-weight: bold;
    margin-top: 2mm;
}

.qr-section {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-top: 3mm;
    padding-top: 3mm;
    border-top: 1px dashed #000;
}

.qr-box {
    text-align: center;
    margin: 2mm 0;
}

.qr-box img {
    width: 28mm;
    height: 28mm;
}

.qr-label {
    font-size: 10px;
    margin-top: 1mm;
    font-weight: bold;
}

.qr-doc-id {
    font-size: 9px;
    color: #000;
}

.cut-line {
    border-top: 1px dashed #000;
    margin-top: 3mm;
    text-align: center;
    font-size: 9px;
    color: #000;
}
</style>

{#
  Which company's header to print. Chosen per print job by the `brand` query
  parameter, so the terminal's print menu can offer SMT and MD off one format
  instead of a duplicated template per company. Unknown or absent -> SMT, which
  keeps every existing link and Desk print unchanged.
#}
{% set BRANDS = {
    'SMT': {
        'name_en': 'Scrap Metal Trading',
        'name_th': '',
        'addr': '88/88 หมู่ 1 ต.ท่าไม้ อ.ลาดหลุมแก้ว จ.ปทุมธานี'
    },
    'MD': {
        'name_en': 'MD Recycle Group',
        'name_th': 'บริษัท เอ็มดี รีไซเคิล กรุ๊ป จำกัด',
        'addr': '41/1 อาคาร 2714 ห้องเลขที่ 308-309 ซ.พระรามที่ 2 ซ. 54 แขวงแสมดำ เขตบางขุนเทียน กรุงเทพมหานคร 10150'
    }
} %}
{#
  Brand selection, in priority order:
    1. `brand` query param  - what the truck terminal's print menu sends
    2. `letterhead` param   - the Letter Head dropdown in the Desk print view,
                              so Desk can pick a company without a custom control
    3. SMT                  - anything unrecognised, so old links and any site
                              whose Letter Head is named something else (the dev
                              site's is "metal") keep rendering as they did.
#}
{% set _sel = frappe.form_dict.get('brand') or frappe.form_dict.get('letterhead') %}
{% set BRAND = BRANDS.get(_sel, BRANDS['SMT']) %}

{% set photo_count = doc.photos | length if doc.photos else 0 %}

<div class="thermal-receipt">
    <!-- Header -->
    <div class="receipt-header">
        <div class="company-name">{{ BRAND.name_en }}</div>
        {% if BRAND.name_th %}<div class="company-name-th">{{ BRAND.name_th }}</div>{% endif %}
        <div class="company-address">{{ BRAND.addr }}</div>
        <div class="doc-title">ใบชั่งรถ{% if doc.is_reweight %} (ชั่งซ้ำ){% endif %}</div>
        <div class="doc-number">เลขที่: {{ doc.name }}</div>
    </div>

    <!-- Body -->
    <div class="receipt-body">
        <!-- Weight Display (large) -->
        <div class="weight-display">
            <div class="weight-value-huge">{{ "%.2f"|format(doc.weight) }}</div>
            <div class="weight-unit">Kg</div>
        </div>

        <!-- Weight Type Indicator (checkboxes) -->
        <div class="weight-type-row">
            <div class="weight-type-option {% if doc.weight_type == 'Gross' %}checked{% endif %}">
                <span class="checkbox">{% if doc.weight_type == 'Gross' %}[X]{% else %}[ ]{% endif %}</span>
                <span class="option-label">{{ "ขาออก" if is_pickup else "ขาเข้า" }}<br>Gross</span>
            </div>
            <div class="weight-type-option {% if doc.weight_type == 'Tare' %}checked{% endif %}">
                <span class="checkbox">{% if doc.weight_type == 'Tare' %}[X]{% else %}[ ]{% endif %}</span>
                <span class="option-label">{{ "ขาเข้า" if is_pickup else "ขาออก" }}<br>Tare</span>
            </div>
        </div>

        <!-- Date/Time & License Info -->
        <div class="info-section">
            <div class="info-row">
                <span class="info-label">วันที่/เวลา:</span>
                <span class="info-value">{{ frappe.utils.format_datetime(doc.weighed_at, 'dd/MM/yyyy HH:mm') if doc.weighed_at else '' }}</span>
            </div>
            <div class="info-row">
                <span class="info-label">ทะเบียนรถ:</span>
                <span class="info-value">{{ doc.license_plate or '-' }}</span>
            </div>
            <div class="info-row">
                <span class="info-label">{{ "Pickup:" if is_pickup else "Drop-off:" }}</span>
                <span class="info-value">{{ (doc.pickup if is_pickup else doc.dropoff) or "-" }}</span>
            </div>
        </div>

        <!-- Supplier Info -->
        <div class="info-section">
            <div class="info-row">
                <span class="info-label">{{ "ลูกค้า:" if is_pickup else "ผู้ขาย:" }}</span>
                <span class="info-value">{{ party_name or "-" }}</span>
            </div>
        </div>

        <!-- Entry Method & Photos (inline) -->
        <div class="info-row-box">
            <div class="info-box-item">
                <span class="box-label">วิธีบันทึก:</span>
                {% if doc.entry_method == 'Scale (Auto)' %}
                <span class="box-value">[A] Scale</span>
                {% else %}
                <span class="box-value">[M] Manual</span>
                {% endif %}
            </div>
            <div class="info-box-item">
                <span class="box-label">รูปภาพ:</span>
                {% if photo_count > 0 %}
                <span class="box-value">{{ photo_count }} รูป</span>
                {% else %}
                <span class="box-value">ไม่มี</span>
                {% endif %}
            </div>
        </div>

        <!-- Reweight Info -->
        {% if doc.is_reweight %}
        <div class="reweight-badge">
            ** ชั่งซ้ำ **
            {% if doc.reweight_reason %}<br>{{ doc.reweight_reason }}{% endif %}
        </div>
        {% endif %}

        <!-- Remarks -->
        {% if doc.remarks %}
        <div class="remarks-section">
            <strong>หมายเหตุ:</strong> {{ doc.remarks }}
        </div>
        {% endif %}
    </div>

    <!-- Footer -->
    <div class="receipt-footer">
        <div class="operator-info">
            ผู้ชั่ง: {{ frappe.db.get_value('User', doc.operator, 'full_name') or doc.operator or '-' }}
        </div>
        {% if doc.scale %}
        <div class="operator-info">
            เครื่องชั่ง: {{ frappe.db.get_value('Scale', doc.scale, 'scale_name') or doc.scale }}
        </div>
        {% endif %}
        <div class="operator-info">
            พิมพ์เมื่อ: {{ frappe.utils.now_datetime().strftime('%d/%m/%Y %H:%M:%S') }}
        </div>
        <div class="thank-you">ขอบคุณที่ใช้บริการ</div>
    </div>

    <!-- QR Codes Section (Bottom, Vertical Stack) -->
    <div class="qr-section">
        {% if doc.dropoff %}
        <div class="qr-box">
            <img src="{{ qr_src('Dropoff', doc.dropoff) }}">
            <div class="qr-label">Drop-off</div>
            <div class="qr-doc-id">{{ doc.dropoff }}</div>
        </div>
        {% endif %}

        <div class="qr-box">
            <img src="{{ qr_src('Truck Weight', doc.name) }}">
            <div class="qr-label">ใบชั่งรถ / Truck</div>
            <div class="qr-doc-id">{{ doc.name }}</div>
        </div>
    </div>

    <div class="cut-line">- - - - - - - - - - - - - - -</div>
</div>
